"""Reports generated exclusively from the current active catalog and recomputed estimates."""
import pathlib,json,html,sys,collections
R=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'app'))
from presentation import fa,unit
from engine import number
from estimation import METHOD_NAMES
def build_reports():
 p=R/'data/panel_2005_2024';d=json.loads((p/'dashboard_data.json').read_text('utf8'));a=json.loads((p/'analysis_with_estimates.json').read_text('utf8'));v=json.loads((p/'estimation_details.json').read_text('utf8'));s=a['estimation_summary'];meta={m['code']:m for m in d['catalog']};out=R/'reports';out.mkdir(exist_ok=True)
 def page(title,body):return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>body{font:14px/2 Tahoma;background:#eef2f7;color:#21324b}main{max-width:1050px;margin:30px auto;padding:35px;background:white;border-radius:14px}h1{font-size:25px}h2{font-size:18px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:right;padding:10px;border-bottom:1px solid #ddd}th{background:#eaf0f7}.estimate{color:#bd243e;font-weight:bold}.note{padding:12px;background:#fff0f1;border-right:4px solid #bd243e}a{color:#096e9d}@media print{body{background:white}main{margin:0;padding:10px}}</style><main><h1>'+title+'</h1>'+body+'</main></html>'
 def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
 rows=[]
 for code in d['core']:
  x=next(x for x in d['comparison'] if x['indicator']==code);rows.append([fa(x['name_fa']),str(x['common_years'])+'/۲۰',number(x['IRN_first'])+' ← '+number(x['IRN_last']),number(x['EGY_first'])+' ← '+number(x['EGY_last']),unit(meta[code])])
 body=f'<p>بازهٔ ثابت: <b>۲۰۰۵ تا ۲۰۲۴</b>، دقیقاً بیست سال. مجموعه شامل <b>{d["summary"]["source_metrics"]} شاخص منبع و {d["summary"]["derived_metrics"]} شاخص محاسبه‌شده</b> است. قاعدهٔ عمومی حداکثر پنج سال مقدار منتشرنشده در هر کشور است؛ رتبهٔ نوآوری، صادرات فناوری‌پیشرفته و هزینهٔ تحقیق‌وتوسعه استثناهای صریح‌اند.</p>'
 body+='<p>جدول زیر فقط داده‌های اولیه را روی سال‌های مشترک مقایسه می‌کند؛ ابتدا و انتها برای هر دو کشور هم‌سال‌اند. مقدار بیشتر به‌تنهایی عملکرد بهتر را نشان نمی‌دهد.</p>'+table(['شاخص','سال مشترک','ایران: ابتدا تا انتها','مصر: ابتدا تا انتها','واحد'],rows)
 body+=f'<p class="note">{s["source_estimates"]} مقدار منبع با چهار روش آماری و اعتبارسنجی تخمین زده شده و {s["derived_estimates"]} مقدارِ فرمولی از ورودی تخمینی محاسبه شده است. مجموع <b>{s["estimated_values"]} مقدار</b> در داشبورد و اکسل تکمیلی قرمزند. داده‌های اولیه جدا و دست‌نخورده‌اند.</p>'
 body+='<p>رتبهٔ نوآوری در این فایل فقط برای ۲۰۲۰ تا ۲۰۲۴ موجود است؛ این موضوع به معنی آغاز انتشار شاخص در ۲۰۲۰ نیست. پانزده سال ناموجود برای هر کشور خالی مانده‌اند و برون‌یابی نمی‌شوند.</p><p>منابع هر شاخص، واحد و فرمول در واژه‌نامهٔ داده و اکسل ثبت شده‌اند. رویدادهای تاریخی برای تفسیر و ساخت فرضیه‌اند و هم‌زمانی آن‌ها با تغییر شاخص رابطهٔ علّی را ثابت نمی‌کند.</p><p><a href="Estimation_Methodology_FA.html">متودولوژی و آزمون مستقل تخمین</a></p>'
 body+='<h2>سه شاخص افزوده‌شده</h2>'+table(['شاخص','کشور','سال با مقدار منبع','سال تکمیل پروژه'],[[meta[c]['name_fa'],co,next(x['n_observations'] for x in d['coverage'] if x['indicator']==c and x['country']==co),sum(x['indicator']==c and x['country']==co for x in v['estimates'])] for c in ['TX.VAL.TECH.CD','GB.XPD.RSDV.GD.ZS','SWIID.GINI.DISP'] for co in ['IRN','EGY']])
 body+='<p>جینی درآمد قابل‌تصرف از سوئید، نسخهٔ ۹٫۹۲ آوریل ۲۰۲۶ است: ۱۹ مقدار منتشرشده برای هر کشور، ۲۰۰۵ تا ۲۰۲۳. این ۳۸ مقدار خود برآورد پژوهشگرند، نه پیمایش مستقل سالانه؛ فقط دو مقدار ۲۰۲۴ تخمین اضافهٔ پروژه‌اند. مقیاس صفر تا صد است و با جینی مصرف بانک جهانی ترکیب نشده است. منابع: <a href="https://fsolt.org/swiid/">سوئید و مقالهٔ روش</a>، <a href="https://data.worldbank.org/indicator/TX.VAL.TECH.CD">صادرات فناوری‌پیشرفته</a>، <a href="https://data.worldbank.org/indicator/GB.XPD.RSDV.GD.ZS">هزینهٔ تحقیق‌وتوسعه</a>.</p>'
 short=page('ایران و مصر؛ فناوری و نوآوری',body)
 for name in ['Iran_Egypt_Short_Report_FA.html','Iran_Egypt_Data_Report_FA.html']:(out/name).write_text(short,encoding='utf8')
 (out/'Iran_Egypt_Data_Report_FA.md').write_text(f'# ایران و مصر؛ فناوری و نوآوری\n\n۲۰۰۵ تا ۲۰۲۴؛ {len(meta)} شاخص فعال. حداکثر پنج سال مفقود در هر کشور؛ رتبهٔ نوآوری، صادرات فناوری‌پیشرفته و هزینهٔ تحقیق‌وتوسعه استثنا هستند. {s["estimated_values"]} مقدار تکمیلی، با برچسب تخمین. گزارش کامل و منابع در فایل‌های HTML و واژه‌نامهٔ داده قرار دارند.\n',encoding='utf8')
 matches=collections.Counter(x['match'] for x in v['decisions']);methods='، '.join(METHOD_NAMES[k]+': '+str(n) for k,n in s['methods'].items())
 body=f'<p>برای مجموعهٔ جاریِ {len(meta)} شاخص، {s["source_estimates"]} مقدار منبع تخمین زده شد و {s["derived_estimates"]} مقدار از ورودی تخمینی محاسبه شد. تمام {s["estimated_values"]} مقدار تکمیلی قرمزند؛ هیچ مقدار اولیه جایگزین نشده است.</p>'
 body+='<h2>چهار روش نامزد</h2><ol><li><b>میانگین وزنی:</b> ترکیب دو سر شکاف با وزن معکوس فاصله؛ در ابتدا یا انتهای سری، میانگین سه مشاهدهٔ نزدیک.</li><li><b>روند محلی تعدیل‌شده:</b> خط روی نزدیک‌ترین پنج مشاهده، با وزن فاصله و جریمهٔ شیب ۰٫۳.</li><li><b>منحنی روند:</b> منحنی درجهٔ دوم پس از تبدیل لگاریتم یک‌به‌علاوه برای مقادیر غیرمنفی و تبدیل سینوس هیپربولیک معکوس برای سری علامت‌دار؛ جریمهٔ شیب ۰٫۰۵ و انحنا ۰٫۵.</li><li><b>وضعیت پنهان:</b> مدل سطح و شیب با فیلتر کالمن و هموارساز پسرو. پراکندگی تفاضل‌های سالانهٔ آموزش مبنای واریانس است؛ ضرایب سطح، شیب و مشاهده به‌ترتیب ۰٫۲۵، ۰٫۰۲ و ۰٫۱۵ هستند. تنظیمات از پیش تعیین‌شده‌اند و با بیشینه‌سازی درست‌نمایی برازش نشده‌اند.</li></ol>'
 body+='<h2>اعتبارسنجی با پنهان‌سازی دادهٔ معلوم</h2><p>برای هر کشور، شاخص، جهت و طول شکاف، پنجره‌های پیوستهٔ معلوم عمداً مخفی می‌شوند. حداقل سه مشاهده برای آموزش باقی می‌ماند و حداکثر هشت پنجره با پخش یکنواخت انتخاب می‌شود. هر چهار روش روی پنجره‌های یکسان آزموده و روشِ دارای کمترین میانگین قدرمطلق خطا انتخاب می‌شود. در انتهای سری فقط گذشته، در ابتدای سری فقط آیندهٔ باقی‌مانده و در شکاف داخلی هر دو طرف مجاز است. مقدار پنهان در برازش، مقیاس‌سازی یا تنظیم پراکندگی وارد نمی‌شود.</p>'
 body+=f'<p>تعداد تصمیم‌ها: {len(v["decisions"])}؛ آزمون هم‌طول: {matches["matched"]}؛ شکاف کوتاه‌تر: {matches["shorter_gap_fallback"]}؛ مشاهدهٔ منفرد: {matches["sparse_fallback"]}. تعداد مقایسهٔ روش–نقطه: {s["validation_trials"]}؛ این تعداد مشاهدهٔ مستقل نیست. شمار تخمین‌های منتخب: {methods}.</p>'
 body+=f'<h2>ارزیابی مستقل فرایند انتخاب</h2><p>در آزمون تو‌در‌تو، یک پنجرهٔ بیرونی پنهان شد؛ انتخاب روش فقط در دادهٔ باقی‌مانده انجام گرفت و سپس پنجرهٔ بیرونی با مقدار واقعی مقایسه شد. نخستین {s["outer_validation_patterns"]} الگوی واجد شرایطِ مجموعهٔ فعال، شامل {s["outer_validation_points"]} نقطه، آزموده شدند. میانگین خطای مطلق تقسیم بر میانگین قدرمطلق آموزش، <b>{s["nested_normalized_MAE"]*100:.2f}٪</b> بود. این معیار «درصد دقت» نیست و نمایندهٔ تضمین‌شدهٔ همهٔ شاخص‌ها یا شکاف‌ها نیست.</p>'
 body+='<p>حدود تشخیصیِ فایل جزئیات از صدک نود خطای مطلق آزمون ساخته می‌شوند؛ این حدود فاصلهٔ اطمینان کالیبره‌شده نیستند. سهم‌های واقعاً محدود به صفر تا صد در همان محدوده نگه داشته می‌شوند. رتبهٔ ناموجود تخمین زده نمی‌شود. شاخص فرمولی از ورودی همان سال محاسبه می‌شود و اگر ورودی تخمینی باشد، خروجی نیز برچسب تخمین می‌گیرد.</p>'
 body+='<p>تمام عددها، روش منتخب، خطاها، سال‌های آموزش و پنهان‌شده و آزمون بیرونی در فایل‌های جداگانهٔ estimation_*.csv ثبت شده‌اند. بازتولید: اجرای build_estimates.py پس از build_panel20.py.</p><p>مبانی: <a href="https://www.statsmodels.org/stable/examples/notebooks/generated/statespace_local_linear_trend.html">روند خطی محلی و وضعیت پنهان</a> و <a href="https://otexts.com/fpp3/tscv.html">اعتبارسنجی سری زمانی</a>. قواعد جریمه و انتخاب پنجره طراحی این پروژه‌اند.</p>'
 (out/'Estimation_Methodology_FA.html').write_text(page('متودولوژی تخمین و اعتبارسنجی',body),encoding='utf8')
 selected=[x for x in v['decisions'] if x['indicator'] in {'TX.VAL.TECH.CD','GB.XPD.RSDV.GD.ZS','SWIID.GINI.DISP'}]
 extra='<h2>اعتبارسنجی سه شاخص افزوده‌شده</h2>'+table(['شاخص','کشور','سال‌های تکمیل','روش منتخب','طول شکاف / آزمون','خطای مطلق میانگین'],[[meta[x['indicator']]['name_fa'],x['country'],x['target_years'],x['method_fa'],str(x['gap_length'])+' / '+str(x['validated_length']),number(x['validation_MAE'])] for x in selected])
 (out/'Estimation_Methodology_FA.html').write_text(page('متودولوژی تخمین و اعتبارسنجی',body+extra),encoding='utf8')
 from i18n import METHOD_EN
 def english_page(title,body):return page(title,body).replace('lang="fa" dir="rtl"','lang="en" dir="ltr"').replace('text-align:right','text-align:left')
 coverage=table(['Indicator','Country','Published source years / 20','Project-estimated years'],[[meta[c]['name_en'],co,next(x['n_observations'] for x in d['coverage'] if x['indicator']==c and x['country']==co),sum(x['indicator']==c and x['country']==co for x in v['estimates'])] for c in ['TX.VAL.TECH.CD','GB.XPD.RSDV.GD.ZS','SWIID.GINI.DISP'] for co in ['IRN','EGY']])
 en=f'<p>Fixed period: 2005–2024. {len(meta)} indicators: {d["summary"]["source_metrics"]} source and {d["summary"]["derived_metrics"]} derived. At most five missing years per country is the general rule; innovation rank, high-technology exports and R&amp;D expenditure are explicit exceptions.</p>'+coverage
 en+=f'<p>{s["source_estimates"]} missing source values were estimated by the project; {s["derived_estimates"]} derived values use estimated inputs. All {s["estimated_values"]} project estimates are identified in red in the dashboard and completed workbook. Source values are preserved separately.</p>'
 en+='<p>Disposable-income Gini is taken from SWIID 9.92 (April 2026), variable gini_disp, scale 0–100. Both countries have published values for every year in 2005–2023; only 2024 is filled by the project. Those 38 source values are standardized researcher estimates, not 38 independent annual household surveys. They are not spliced to World Bank consumption Ginis. SWIID standard errors are retained in the source data; validation against SWIID does not measure its own survey or harmonization uncertainty.</p><p>Sources: <a href="https://fsolt.org/swiid/">SWIID and Solt (2020), Social Science Quarterly 101(3):1183–1199</a>; <a href="https://data.worldbank.org/indicator/TX.VAL.TECH.CD">World Bank high-technology exports</a>; <a href="https://data.worldbank.org/indicator/GB.XPD.RSDV.GD.ZS">World Bank / UNESCO R&amp;D expenditure</a>. Source URLs and formulas for all indicators are in the data dictionary. Historical events provide context, not proof of causation.</p>'
 for name in ['Iran_Egypt_Short_Report_EN.html','Iran_Egypt_Data_Report_EN.html']:(out/name).write_text(english_page('Iran and Egypt: technology and innovation',en),encoding='utf8')
 en+='<h2>Estimation methods and validation</h2><ol><li>Distance-weighted average: interpolation between neighboring observations; at a boundary, the three nearest observations are weighted by inverse distance.</li><li>Regularized local trend: distance-weighted linear fit to five nearest observations; slope penalty 0.3.</li><li>Trend curve: regularized quadratic after log1p for nonnegative values or inverse hyperbolic sine for signed values; slope and curvature penalties 0.05 and 0.5.</li><li>Latent state: level and slope with a Kalman filter and backward smoother. Robust training differences set variance; level, slope and observation multipliers are 0.25, 0.02 and 0.15. These are fixed project settings, not maximum-likelihood estimates.</li></ol>'
 en+='<p>Artificial missingness validation hides known source values in contiguous windows with matching gap direction and length. All four methods use the same windows, at least three training observations, and up to eight spread-out folds. Trailing gaps use past values only; leading gaps use remaining future values; internal gaps use both sides. Hidden values never enter fitting, scaling or variance calibration. The lowest mean absolute error wins. When no matched window is available, shorter or single-point tests are explicitly reported; extrapolation to longer gaps is less certain.</p>'
 en+=f'<p>{s["validation_trials"]} method–point comparisons were run (not independent observations). Independent nested validation covered the first {s["outer_validation_patterns"]} eligible patterns and {s["outer_validation_points"]} points. Mean absolute error divided by mean absolute training value was {s["nested_normalized_MAE"]*100:.2f}%. This is not an accuracy percentage or a guarantee for all gaps.</p>'
 en+='<p>The three-year trailing R&amp;D gap for Iran was validated using two-year windows because a matched three-year test was unavailable; applying that result to three years requires greater caution.</p>'
 en+=table(['Indicator','Country','Filled years','Method','Actual / validated gap length','MAE'],[[meta[x['indicator']]['name_en'],x['country'],x['target_years'],METHOD_EN[x['method']],str(x['gap_length'])+' / '+str(x['validated_length']),number(x['validation_MAE'])] for x in selected])
 en+='<p>Full trials, masks, training years, decisions and outer checks are in estimation_*.csv. Diagnostic bounds use the 90th percentile of validation absolute errors and are not calibrated confidence intervals. References: <a href="https://otexts.com/fpp3/tscv.html">time-series cross-validation</a> and <a href="https://www.statsmodels.org/stable/examples/notebooks/generated/statespace_local_linear_trend.html">local linear trend state-space model</a>. Window selection and regularization settings are project design choices.</p>'
 (out/'Estimation_Methodology_EN.html').write_text(english_page('Estimation methodology and validation',__import__('re').sub(r'<p>Disposable-income Gini is taken.*?</p>','',en)),encoding='utf8')
 print('Regenerated current reports')
if __name__=='__main__':build_reports()
